import {uid,initialState,newSet,toDisplay,toKg,validSet,workingSets,volume,bestFor,previousEntries,startWorkout,finishWorkout,normalizeGroups,validateBackup,csvExport,localDay,activityDays,routineEditorFor,routineFromEditor} from './core.mjs';
import {createViews,esc,num,date,longdate,duration} from './views.mjs';
import {applyAppearance,appearanceControls,setupView,ratingControls,ratingBadge} from './preferences.mjs';
import {routineEditorView,exerciseResults} from './routines.mjs';
const $=s=>document.querySelector(s);
const routineInvalid=new Map();
let routineEditor=null,routineSnapshot='',setupDraft=null,pickerMuscle='All',pickerQuery='',routineFilter='All',historyFilter='All';
const editableWorkout=()=>routineEditor||state.draft;
const persistEdits=()=>routineEditor?Promise.resolve(true):persist();
function navigate(to){const go=()=>{routineEditor=null;view=to;close();render();window.scrollTo(0,0)};if(routineEditor&&JSON.stringify(routineEditor)!==routineSnapshot)confirmAction('Discard routine changes?','Your saved routine will stay as it was.','Discard changes',go);else go()}
function editRoutine(routine){routineInvalid.clear();routineEditor=routineEditorFor(routine);routineSnapshot=JSON.stringify(routineEditor);close();render();window.scrollTo(0,0)}
async function saveRoutine(){for(const input of document.querySelectorAll('[aria-label="Routine editor"] input'))if(!input.reportValidity())return;try{const routine=routineFromEditor(routineEditor),candidate=structuredClone(state),index=candidate.routines.findIndex(r=>r.id===routine.id);if(index<0)candidate.routines.push(routine);else candidate.routines[index]=routine;const clean=validateBackup(candidate),before=state;state=clean;if(await persist()){routineEditor=null;routineFilter='All';view='workout';render();toast('Routine saved');window.scrollTo(0,0)}else state=before}catch(e){toast(e.message)}}
function updatePreference(key,value){const p=state.settings.setupComplete?state.settings:(setupDraft||=structuredClone(state.settings));p[key]=key==='rest'?Number(value):value;applyAppearance(p);if(state.settings.setupComplete)persist();render()}
function finishDialog(){const done=state.draft.entries.flatMap(e=>e.sets).filter(s=>s.done).length;if(!done){toast('Complete at least one set first.');return}openModal('A session in the books.',`<p class="help">${done} completed sets will be saved. Unchecked sets will be left out.</p>${ratingControls(state.draft.rating,'draft')}<button class="primary wide" data-action="finish-confirmed">Finish and save</button>`)}

let revision=0;
let state,db,view='workout',period=30,selectedExercise='',saveQueue=Promise.resolve(),saveError='',foreignChange=false,finishing=false,offlineReady=false;
const sourceId=uid(),channel=typeof BroadcastChannel!=='undefined'?new BroadcastChannel('setline'):null;
const ex=id=>state.exercises.find(e=>e.id===id),weight=n=>num(toDisplay(n,state.settings.unit));
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function openModal(title,html){const d=$('#modal');d.innerHTML=`<button class="close" data-action="close" aria-label="Close dialog">×</button><h2>${esc(title)}</h2>${html}`;if(!d.open)d.showModal()}
const close=()=>$('#modal').close();
function confirmAction(title,message,yes,callback){openModal(title,`<p class="help" style="margin-top:18px">${esc(message)}</p><div class="modal-actions"><button class="secondary" data-action="close">Cancel</button><button class="primary" id="confirm">${esc(yes)}</button></div>`);$('#confirm').onclick=async()=>{close();await callback()}}
async function initialize(){try{db=await new Promise((resolve,reject)=>{const r=indexedDB.open('setline',1);r.onupgradeneeded=()=>r.result.createObjectStore('data');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});const stored=await new Promise((resolve,reject)=>{const t=db.transaction('data'),store=t.objectStore('data'),r=store.get('state'),v=store.get('revision');t.oncomplete=()=>{revision=v.result||0;resolve(r.result)};t.onerror=()=>reject(t.error)});state=stored?validateBackup(stored):initialState();state.settings.schedule??=[];state.settings.scheduleHistory??=[];state.settings.trackingSince??=localDay();render();if(!stored)await persist()}catch(e){$('#app').innerHTML='<main><h1>Storage is unavailable</h1><p class="muted">Setline could not open your saved data. Try a normal Safari tab with private browsing off, then reload. Existing data has not been overwritten.</p></main>';console.error(e);return}if('serviceWorker'in navigator){try{await navigator.serviceWorker.register('./sw.js');await navigator.serviceWorker.ready;offlineReady=true;if(view==='settings')render()}catch{offlineReady=false}}registerTools()}
function persist(){const snapshot=structuredClone(state);saveQueue=saveQueue.then(()=>new Promise(resolve=>{if(foreignChange){saveError='Setline changed in another tab. Export a backup here, then reload before continuing.';showSaveError();resolve(false);return}try{const t=db.transaction('data','readwrite'),store=t.objectStore('data'),r=store.get('revision');let next=revision;r.onsuccess=()=>{const current=r.result||0;if(current!==revision){foreignChange=true;t.abort();return}next=current+1;store.put(snapshot,'state');store.put(next,'revision')};t.oncomplete=()=>{revision=next;saveError='';showSaveError();channel?.postMessage({sourceId});resolve(true)};t.onerror=t.onabort=()=>{saveError=foreignChange?'Setline changed in another tab. Export a backup here, then reload before continuing.':'Could not save on this device. Keep this page open and export a backup in Settings.';showSaveError();resolve(false)}}catch{saveError='Could not save on this device. Export a backup in Settings.';showSaveError();resolve(false)}}));return saveQueue}

function showSaveError(){let b=$('#save-error');if(saveError){if(!b){b=document.createElement('div');b.id='save-error';b.className='error-banner';$('#app').prepend(b)}b.textContent=saveError}else b?.remove()}
channel?.addEventListener('message',e=>{if(e.data.sourceId!==sourceId){foreignChange=true;saveError='Setline changed in another tab. Export a backup here, then reload before continuing.';showSaveError()}});
function render(){if(!state)return;const setup=!state.settings.setupComplete;if(setup)setupDraft||=structuredClone(state.settings);applyAppearance(setup?setupDraft:state.settings);const views=createViews(state,period,selectedExercise,offlineReady,routineFilter,historyFilter);$('#app').innerHTML=`<header class="topbar"><a class="brand" href="#workout"><span class="mark">s/</span> SETLINE</a><span class="eyebrow">${setup?'MAKE IT YOURS':state.draft?'SESSION IN PROGRESS':'YOUR TRAINING LOG'}</span></header><main>${setup?setupView(setupDraft):routineEditor?routineEditorView(routineEditor,state):views[view]()}</main>${setup?'':`<nav class="nav" aria-label="Main navigation">${[['workout','Workout'],['history','History'],['progress','Progress'],['settings','Settings']].map(([id,label])=>`<button data-nav="${id}" class="${view===id&&!routineEditor?'active':''}" ${view===id&&!routineEditor?'aria-current="page"':''}>${label}</button>`).join('')}</nav>`}`;showSaveError();if(routineEditor)for(const input of document.querySelectorAll('[data-set]')){const issue=routineInvalid.get(input.dataset.set);if(issue){input.value=issue.value;input.setCustomValidity(issue.message)}}tick()}
function exercisePicker(reset=true){if(reset){pickerMuscle='All';pickerQuery=''}openModal(routineEditor?'Build your routine':'Add exercise',`<input class="search" id="exercise-search" type="search" placeholder="Find an exercise" value="${esc(pickerQuery)}" aria-label="Search exercises"><div id="exercise-results"></div><button class="secondary wide" data-action="custom-exercise">＋ Create custom exercise</button>${routineEditor?'<button class="primary wide" data-action="close">Done · back to routine</button>':''}`);filterExercises(pickerQuery);$('#exercise-search').oninput=e=>filterExercises(e.target.value)}
function filterExercises(query){pickerQuery=query;$('#exercise-results').innerHTML=exerciseResults(state,query,pickerMuscle,routineEditor)}
function addExercise(id){const target=editableWorkout();if(!target||!ex(id))throw Error('Start a workout or routine and choose a valid exercise.');const prev=!routineEditor&&previousEntries(state.workouts,id)[0]?.entries.find(e=>e.exerciseId===id);target.entries.push({id:uid(),exerciseId:id,group:null,sets:prev?prev.sets.map(s=>newSet(s.weight,s.reps,s.type)):Array.from({length:3},()=>newSet(null,routineEditor?8:null))});if(routineEditor){render();if(!$('#exercise-results'))exercisePicker(false);else filterExercises(pickerQuery);toast(ex(id).name+' added')}else{persist();close();render()}}

function exerciseHistory(id){const ws=previousEntries(state.workouts,id),best=bestFor(state.workouts,id);openModal(ex(id)?.name||'Exercise history',`<p class="help">${best.weight!==null?`Personal record: ${weight(best.weight)} ${state.settings.unit} · Estimated 1RM: ${best.e1rm!==null?weight(best.e1rm)+' '+state.settings.unit:'—'}`:'No completed working sets yet.'}</p>${ws.length?ws.map(w=>`<div class="setting"><div class="row between"><strong>${date(w.started)}</strong><span class="muted">${esc(w.name)}</span></div><p style="margin-bottom:0">${w.entries.filter(e=>e.exerciseId===id).flatMap(e=>e.sets).map(s=>`${weight(s.weight)} ${state.settings.unit} × ${s.reps}${s.type!=='normal'?' ('+s.type+')':''}`).join('<br>')}</p></div>`).join(''):'<p class="empty">Your completed sets will appear here next time.</p>'}`)}
function showWorkout(id){const w=state.workouts.find(w=>w.id===id);if(!w)return;openModal(w.name,`<p class="help">${longdate(w.started)} · ${duration(w)} min · ${weight(volume(w))} ${state.settings.unit}</p>${w.entries.map(e=>`<div class="setting"><h3>${esc(ex(e.exerciseId)?.name)}</h3>${e.group?'<span class="badge">Superset</span>':''}<p>${e.sets.map((s,i)=>`${i+1}. ${weight(s.weight)} ${state.settings.unit} × ${s.reps}${s.type!=='normal'?' · '+s.type:''}`).join('<br>')}</p></div>`).join('')}${w.notes?`<p class="note">${esc(w.notes)}</p>`:''}${ratingControls(w.rating,w.id)}<button class="primary wide" data-repeat="${w.id}">Repeat workout</button><button class="quiet danger wide" data-delete-workout="${w.id}">Delete workout</button>`)}
function begin(routine){if(state.draft){view='workout';close();render();toast('Your current workout is still in progress.');return}state.draft=startWorkout(state,routine);state.settings.restEnds=null;persist();view='workout';close();render();window.scrollTo(0,0)}
function scheduleDialog(){openModal('Your training days',`<p class="help">Choose the days you usually train. A planned day becomes “missed” after that day ends. Days without a plan are rest days. Changes apply from today; previous days keep their original plan.</p><div class="schedule-choices">${[1,2,3,4,5,6,0].map(i=>`<label><input type="checkbox" name="day" value="${i}" ${state.settings.schedule.includes(i)?'checked':''}> ${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][i]}</label>`).join('')}</div><button class="primary wide" id="save-schedule">Save training days</button>`);$('#save-schedule').onclick=()=>{state.settings.schedule=[...$('#modal').querySelectorAll('input:checked')].map(e=>Number(e.value));const today=localDay();state.settings.scheduleHistory=state.settings.scheduleHistory.filter(p=>p.from!==today);state.settings.scheduleHistory.push({from:today,days:[...state.settings.schedule]});persist();close();render();toast('Training days saved')}}
function setRef(value){const [e,s]=value.split('/');const entry=editableWorkout()?.entries.find(x=>x.id===e);return {entry,set:entry?.sets.find(x=>x.id===s)}}
function tick(){if(!state)return;if($('#elapsed')&&state.draft)$('#elapsed').textContent=duration(state.draft)+' min';const remaining=Math.max(0,Math.ceil(((state.settings.restEnds||0)-Date.now())/1000));if($('#rest-timer')){$('#rest-timer').classList.toggle('hidden',!remaining);$('#rest-count').textContent=`${Math.floor(remaining/60)}:${String(remaining%60).padStart(2,'0')}`}if(state.settings.restEnds&&remaining===0){state.settings.restEnds=null;persist();toast('Rest complete. Ready for your next set.');navigator.vibrate?.([100,60,100])}}
setInterval(tick,1000);
async function download(text,name,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}
async function finish(){if(finishing||!state.draft)return;finishing=true;try{const w=finishWorkout(state.draft);const records=w.entries.filter(e=>{const before=bestFor(state.workouts,e.exerciseId).weight,after=bestFor([w],e.exerciseId).weight;return before!==null&&after!==null&&after>before+1e-8});state.workouts.push(w);state.draft=null;state.settings.restEnds=null;const saved=await persist();view='history';render();openModal(saved?'Session saved.':'Session recorded in memory',`<p class="help">${workingSets(w).length} working sets · ${weight(volume(w))} ${state.settings.unit} moved · ${duration(w)} minutes.</p>${records.length?`<p class="badge">${records.length} new personal ${records.length===1?'record':'records'}</p><p>${records.map(e=>esc(ex(e.exerciseId).name)).join('<br>')}</p>`:''}${ratingBadge(w.rating)}${!saved?'<p class="note">Device storage failed. Export a backup from Settings before closing the app.</p>':''}<button class="primary wide" data-action="close">Keep it going</button>`)}catch(e){toast(e.message)}finally{finishing=false}}
document.addEventListener('input',e=>{const t=e.target;if(t.hasAttribute('data-routine-name')&&routineEditor)routineEditor.name=t.value;if(t.dataset.field&&state.draft){state.draft[t.dataset.field]=t.value;persistEdits()}if(t.dataset.set){const {set}=setRef(t.dataset.set);if(!set)return;const field=t.dataset.set.split('/')[2];let value=t.value===''?null:Number(t.value);if(t.validity.badInput)value=NaN;if(value!==null){if(!Number.isFinite(value)||value<0||(field==='reps'&&(!Number.isInteger(value)||value<1||value>1000))||(field==='weight'&&toKg(value,state.settings.unit)>10000)){const message=field==='reps'?'Enter 1–1000 whole reps, or leave it blank.':'Enter a weight of 0 or more, or leave it blank.';t.setCustomValidity(message);if(routineEditor)routineInvalid.set(t.dataset.set,{value:t.value,message});set[field]=routineEditor?NaN:null;set.done=false;persistEdits();return}if(field==='weight')value=toKg(value,state.settings.unit)}t.setCustomValidity('');routineInvalid.delete(t.dataset.set);set[field]=value;set.done=false;const row=t.closest('.set-row');row.classList.remove('complete');const b=row.querySelector('.check');if(b){b.setAttribute('aria-pressed','false');b.setAttribute('aria-label',b.getAttribute('aria-label').replace('Uncheck','Complete'));}persistEdits()}});
document.addEventListener('change',async e=>{const t=e.target;if(t.dataset.pref){updatePreference(t.dataset.pref,t.value);return}if(t.id==='unit'){state.settings.unit=t.value;await persist();render()}if(t.id==='rest'){state.settings.rest=Number(t.value);await persist()}if(t.id==='progress-exercise'){selectedExercise=t.value;render()}if(t.id==='import-file'){const file=t.files[0];if(!file)return;try{if(file.size>50e6)throw Error('Backup is too large (50 MB maximum).');const imported=validateBackup(JSON.parse(await file.text()));confirmAction('Restore this backup?',`This replaces ${state.workouts.length} saved workouts with ${imported.workouts.length} workouts from the backup. Export your current data first if you want to keep it.`,'Replace and restore',async()=>{const old=state;state=imported;state.settings.restEnds=null;if(await persist()){setupDraft=null;routineEditor=null;view='history';render();toast('Backup restored')}else{state=old;render()}})}catch(err){toast(err instanceof SyntaxError?'That file is not valid JSON. Nothing was changed.':err.message)}t.value=''}});
document.addEventListener('click',async ev=>{const t=ev.target.closest('button,a');if(!t||!state)return;const d=t.dataset;try{
 if(t.classList.contains('brand')){ev.preventDefault();if(state.settings.setupComplete)navigate('workout')}
 if(d.nav)navigate(d.nav);
 if(d.pref)updatePreference(d.pref,d.value);
 if(d.setupDay!==undefined){const day=Number(d.setupDay);setupDraft.schedule=setupDraft.schedule.includes(day)?setupDraft.schedule.filter(x=>x!==day):[...setupDraft.schedule,day];render()}
 if(d.muscle){pickerMuscle=d.muscle;filterExercises(pickerQuery)}
 if(d.routineFilter){routineFilter=d.routineFilter;render()}
 if(d.historyFilter){historyFilter=d.historyFilter;render()}
 if(d.editRoutine)editRoutine(state.routines.find(r=>r.id===d.editRoutine));
 if(d.rating){const w=d.ratingTarget==='draft'?state.draft:state.workouts.find(w=>w.id===d.ratingTarget);if(w){w.rating=d.rating==='clear'?null:Number(d.rating);persist();render();if(d.ratingTarget==='draft')finishDialog();else showWorkout(w.id)}}
 if(d.routine)begin(state.routines.find(r=>r.id===d.routine));
 if(d.deleteRoutine)confirmAction('Delete routine?','Saved workout history will stay intact.','Delete routine',()=>{state.routines=state.routines.filter(r=>r.id!==d.deleteRoutine);routineEditor=null;persist();render();toast('Routine deleted')});
 if(d.addEx)addExercise(d.addEx);
 if(d.historyEx)exerciseHistory(d.historyEx);
 if(d.workout)showWorkout(d.workout);
 if(d.repeat){const w=state.workouts.find(w=>w.id===d.repeat);begin({name:w.name,items:w.entries.map(e=>({exerciseId:e.exerciseId,group:e.group,sets:e.sets}))})}
 if(d.deleteWorkout)confirmAction('Delete this workout?','This removes the session and recalculates your records.','Delete workout',()=>{state.workouts=state.workouts.filter(w=>w.id!==d.deleteWorkout);persist();render()});
 if(d.period!==undefined){period=Number(d.period);render()}
 if(d.day){const day=activityDays(state,112).find(x=>x.date===d.day),ws=state.workouts.filter(w=>localDay(w.started)===d.day);openModal(longdate(d.day+'T12:00:00'),ws.length?ws.map(w=>`<button class="choice" data-workout="${w.id}">${esc(w.name)}<small>${workingSets(w).length} working sets · ${duration(w)} min</small></button>`).join(''):`<p class="help" style="margin-top:20px">${day?.status==='missed'?'A planned training day with no completed workout.':day?.status==='planned'?'You planned to train today. There is still time.':'Rest day or no training planned.'}</p>`)}
 if(d.addSet||d.drop){const entry=editableWorkout().entries.find(e=>e.id===(d.addSet||d.drop)),last=entry.sets.at(-1);if(d.drop&&(!last||last.type==='warmup')){toast('Add a normal working set before a drop set.');return}entry.sets.push(newSet(Number.isFinite(last?.weight)?last.weight:null,Number.isInteger(last?.reps)?last.reps:null,d.drop?'drop':'normal'));persistEdits();render()}
 if(d.removeSet){const {entry,set}=setRef(d.removeSet);entry.sets=entry.sets.filter(s=>s.id!==set.id);entry.sets.forEach((s,i)=>{if(s.type==='drop'&&(!i||entry.sets[i-1].type==='warmup'))s.type='normal'});persistEdits();render()}
 if(d.complete){const {entry,set}=setRef(d.complete);if(!validSet(set)){toast('Enter a weight (0 for bodyweight) and whole reps first.');return}set.done=!set.done;if(set.done){const pos=entry.sets.indexOf(set),next=entry.sets[pos+1],partners=editableWorkout().entries.filter(e=>e.group&&e.group===entry.group);const more=partners.length>1&&partners.some(e=>e.id!==entry.id&&e.sets[pos]&&!e.sets[pos].done);state.settings.restEnds=!more&&next?.type!=='drop'&&state.settings.rest?Date.now()+state.settings.rest*1000:null;navigator.vibrate?.(25)}persistEdits();render()}
 if(d.setType)openModal('Set type',`<button class="choice" data-type="normal" data-ref="${d.setType}">Working set<small>Counts toward records and volume</small></button><button class="choice" data-type="warmup" data-ref="${d.setType}">Warmup<small>Excluded from records and volume</small></button><button class="choice" data-type="drop" data-ref="${d.setType}">Drop set<small>A lighter step after the previous set</small></button>`);
 if(d.type){const {entry,set}=setRef(d.ref),i=entry.sets.indexOf(set);if(d.type==='drop'&&(!i||entry.sets[i-1].type==='warmup')){toast('A drop set needs a working set before it.');return}set.type=d.type;if(d.type==='warmup'&&entry.sets[i+1]?.type==='drop')entry.sets[i+1].type='normal';persistEdits();close();render()}
 if(d.entryOptions){const entry=editableWorkout().entries.find(e=>e.id===d.entryOptions);openModal(ex(entry.exerciseId).name,`<button class="choice" data-move="${entry.id}" data-direction="-1">Move up</button><button class="choice" data-move="${entry.id}" data-direction="1">Move down</button><button class="choice" data-pair="${entry.id}">Set up superset</button><button class="choice danger" data-remove-entry="${entry.id}">Remove exercise</button>`)}
 if(d.move){const a=editableWorkout().entries,i=a.findIndex(e=>e.id===d.move),j=i+Number(d.direction);if(j>=0&&j<a.length)[a[i],a[j]]=[a[j],a[i]];persistEdits();close();render()}
 if(d.removeEntry)confirmAction('Remove exercise?',routineEditor?'This removes its sets from this routine.':'This removes its sets from the current workout.','Remove',()=>{editableWorkout().entries=editableWorkout().entries.filter(e=>e.id!==d.removeEntry);normalizeGroups(editableWorkout().entries);persistEdits();render()});
 if(d.pair){const a=editableWorkout().entries.find(e=>e.id===d.pair);openModal('Build a superset',`<p class="help">Alternate sets between these exercises before resting.</p>${editableWorkout().entries.filter(e=>e.id!==a.id).map(e=>`<button class="choice" data-pair-target="${e.id}" data-source="${a.id}">${esc(ex(e.exerciseId).name)}</button>`).join('')||'<p class="empty">Add another exercise to pair with this one.</p>'}${a.group?`<button class="quiet danger wide" data-unpair="${a.id}">Remove from superset</button>`:''}`)}
 if(d.pairTarget){const a=editableWorkout().entries.find(e=>e.id===d.source),b=editableWorkout().entries.find(e=>e.id===d.pairTarget),old=b.group,g=a.group||b.group||uid();if(old)editableWorkout().entries.filter(e=>e.group===old).forEach(e=>e.group=g);a.group=b.group=g;normalizeGroups(editableWorkout().entries);persistEdits();close();render()}
 if(d.unpair){editableWorkout().entries.find(e=>e.id===d.unpair).group=null;normalizeGroups(editableWorkout().entries);persistEdits();close();render()}
 if(d.action&&actions[d.action])await actions[d.action]();
 }catch(e){console.error(e);toast(e.message||'Something went wrong. Your session is still here.')}});
const actions={close,start:()=>begin(),'add-exercise':()=>exercisePicker(),schedule:scheduleDialog,
 'new-routine':()=>editRoutine(), 'cancel-routine':()=>navigate('workout'),'commit-routine':saveRoutine,
 'complete-setup':async()=>{const previous=state.settings;state.settings={...setupDraft,setupComplete:true,scheduleHistory:setupDraft.schedule.length?[{from:localDay(),days:[...setupDraft.schedule]}]:[]};if(await persist()){setupDraft=null;render();window.scrollTo(0,0)}else{state.settings=previous;render()}},
 'finish-confirmed':()=>{close();return finish()},
 finish:finishDialog,
 discard:()=>confirmAction('Discard this workout?','All sets in this unfinished session will be removed.','Discard',()=>{state.draft=null;state.settings.restEnds=null;persist();render()}),
 'rest-plus':()=>{state.settings.restEnds=(state.settings.restEnds||Date.now())+30000;persist();tick()},'rest-skip':()=>{state.settings.restEnds=null;persist();tick()},
 'custom-exercise':()=>{openModal('Create an exercise','<label>Name<input id="custom-name" maxlength="120" placeholder="e.g. Cable lateral raise"></label><label>Muscle group<select id="custom-muscle">'+['Chest','Back','Legs','Shoulders','Arms','Core','Other'].map(x=>'<option>'+x+'</option>').join('')+'</select></label><button class="primary wide" id="create-exercise">Create and add</button>');$('#create-exercise').onclick=()=>{const name=$('#custom-name').value.trim();if(!name){toast('Give the exercise a name.');return}if(state.exercises.some(e=>e.name.toLowerCase()===name.toLowerCase())){toast('That exercise already exists. Search for it instead.');return}const exercise={id:uid(),name,muscle:$('#custom-muscle').value};state.exercises.push(exercise);persist();addExercise(exercise.id)}},
 'save-routine':()=>{if(!state.draft?.entries.length){toast('Add an exercise first.');return}editRoutine({id:uid(),name:state.draft.name,items:state.draft.entries.map(e=>({exerciseId:e.exerciseId,group:e.group,sets:e.sets}))})},
 backup:async()=>{const copy=structuredClone(state);copy.settings.lastBackup=new Date().toISOString();await download(JSON.stringify(copy),'setline-backup-'+localDay()+'.json','application/json');state.settings.lastBackup=copy.settings.lastBackup;persist();render();toast('Backup download started')},
 csv:()=>download(csvExport(state),'setline-workouts-'+localDay()+'.csv','text/csv;charset=utf-8'),import:()=>$('#import-file').click(),
 install:()=>openModal('Add Setline to your iPhone','<ol class="help"><li>Open the app link in Safari.</li><li>Tap the Share button.</li><li>Choose Add to Home Screen.</li><li>If shown, enable Open as Web App, then tap Add.</li></ol><p class="note">Install before you start logging. Safari and the installed app may use separate storage. Use backup and restore to move your history.</p>'),
 share:async()=>{const url=location.origin+location.pathname;try{if(navigator.share)await navigator.share({title:'Setline — workout tracker',text:'Track workouts and personal records. Your data stays on your phone.',url});else{await navigator.clipboard.writeText(url);toast('App link copied')}}catch(e){if(e.name!=='AbortError')openModal('Share Setline',`<p class="help">Copy this link and send it to your friends:</p><input readonly aria-label="App link" value="${esc(url)}" style="width:100%">`)}},
 'persist-storage':async()=>{const granted=await navigator.storage?.persist?.();toast(granted?'Persistent storage is enabled. Keep making backups too.':'Your browser manages storage automatically. Regular backups are still best.')}
};
window.addEventListener('hashchange',()=>{if(['workout','history','progress','settings'].includes(location.hash.slice(1))){if(state?.settings.setupComplete)navigate(location.hash.slice(1))}});
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const life=new AbortController();window.addEventListener('pagehide',()=>life.abort(),{once:true});const tool=t=>{try{Promise.resolve(context.registerTool(t,{signal:life.signal})).catch(()=>{})}catch{}};tool({name:'get_workout_summary',title:'Read workout summary',description:'Read counts and the current draft on this device.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:input=>{if(!input||Object.keys(input).length)throw Error('No arguments expected');return {workouts:state.workouts.length,draft:state.draft?{name:state.draft.name,exercises:state.draft.entries.map(e=>ex(e.exerciseId).name)}:null,unit:state.settings.unit}}});tool({name:'open_exercise_history',title:'Open exercise history',description:'Display saved history for an existing exercise. Does not modify workouts.',inputSchema:{type:'object',properties:{exerciseName:{type:'string'}},required:['exerciseName'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:input=>{if(!input||typeof input.exerciseName!=='string'||Object.keys(input).some(k=>k!=='exerciseName'))throw Error('Provide exerciseName only');const exercise=state.exercises.find(e=>e.name.toLowerCase()===input.exerciseName.toLowerCase());if(!exercise)throw Error('Unknown exercise');exerciseHistory(exercise.id);return {exercise:exercise.name,sessions:previousEntries(state.workouts,exercise.id).length}}})}
window.addEventListener('beforeunload',e=>{if(routineEditor&&JSON.stringify(routineEditor)!==routineSnapshot){e.preventDefault();e.returnValue=''}});
initialize();
